sys_ui_page.client_script:
// Code Generated by Sidekick is for learning and experimentation purposes only.
(function () {
  var state = {
    stateGroup: "open",
    sortBy: "sys_updated_on",
    sortDir: "desc",
    page: 0,
    pageSize: 5,
    total: 0
  };

  function esc(s) {
    return (s == null ? "" : String(s))
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function setGreeting() {
    var el = document.getElementById("ri_greeting");
    if (!el) return;
    var name = (typeof g_user !== "undefined" && g_user.getFullName) ? g_user.getFullName() : "";
    el.textContent = name ? ("Hi " + name + ", here are your incidents.") : "Hi, here are your incidents.";
  }

  function setStatus(msg) {
    var el = document.getElementById("ri_status");
    if (el) el.textContent = msg;
  }

  function totalPages() {
    return Math.max(1, Math.ceil((state.total || 0) / state.pageSize));
  }

  function updateSortIndicators() {
    var ths = document.querySelectorAll("#ri_table thead th[data-sort]");
    for (var i = 0; i < ths.length; i++) {
      var th = ths[i];
      var key = th.getAttribute("data-sort") || "";
      var label = th.textContent.replace(/[▲▼]\s*$/, "").trim();
      th.textContent = (key === state.sortBy) ? (label + (state.sortDir === "asc" ? " ▲" : " ▼")) : label;
    }
  }

  function renderPager() {
    var wrap = document.getElementById("ri_pages");
    if (!wrap) return;

    var tp = totalPages();
    wrap.innerHTML = "";

    if (tp <= 1) return;

    for (var p = 0; p < tp; p++) {
      if (p === state.page) {
        var cur = document.createElement("span");
        cur.className = "ri_page current";
        cur.textContent = String(p + 1);
        wrap.appendChild(cur);
      } else {
        var a = document.createElement("a");
        a.className = "ri_page";
        a.href = "#";
        a.textContent = String(p + 1);
        (function (pageIndex, link) {
          link.addEventListener("click", function (e) {
            e.preventDefault();
            state.page = pageIndex;
            load();
          });
        })(p, a);
        wrap.appendChild(a);
      }
    }
  }

  function renderRows(rows) {
    var tbody = document.getElementById("ri_tbody");
    if (!tbody) return;

    tbody.innerHTML = "";

    if (!rows || !rows.length) {
      setStatus("No incidents found.");
      updateSortIndicators();
      renderPager();
      return;
    }

    setStatus("Loaded.");
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i] || {};
      var tr = document.createElement("tr");
      var link = "incident.do?sys_id=" + encodeURIComponent(r.sys_id || "");

      tr.innerHTML =
        '<td><a href="' + esc(link) + '">' + esc(r.number) + "</a></td>" +
        "<td>" + esc(r.short_description) + "</td>" +
        "<td>" + esc(r.state) + "</td>" +
        "<td>" + esc(r.sys_updated_on) + "</td>";

      tbody.appendChild(tr);
    }

    updateSortIndicators();
    renderPager();
  }

  function load() {
    setStatus("Loading…");

    var ga = new GlideAjax("IncidentsForUser");
    ga.addParam("sysparm_name", "getRecentIncidents");
    ga.addParam("sysparm_state_group", state.stateGroup);
    ga.addParam("sysparm_sort_by", state.sortBy);
    ga.addParam("sysparm_sort_dir", state.sortDir);
    ga.addParam("sysparm_page", String(state.page));
    ga.addParam("sysparm_page_size", String(state.pageSize)); // always 5

    ga.getXMLAnswer(function (answer) {
      try {
        var payload = JSON.parse(answer || "{}");
        state.total = payload.total || 0;

        // if filter reduces total pages, clamp current page
        var tp = totalPages();
        if (state.page > tp - 1) state.page = tp - 1;

        renderRows(payload.rows || []);
      } catch (e) {
        setStatus("Error: bad response from server.");
        if (window.console) console.error("Bad response:", answer, e);
      }
    });
  }

  function wireUp() {
    setGreeting();

    var stateSel = document.getElementById("ri_state_group");
    if (stateSel) {
      stateSel.addEventListener("change", function () {
        state.stateGroup = stateSel.value;
        state.page = 0;
        load();
      });
    }

    var ths = document.querySelectorAll("#ri_table thead th[data-sort]");
    for (var i = 0; i < ths.length; i++) {
      (function (th) {
        var key = th.getAttribute("data-sort") || "";
        if (!key) return;

        th.addEventListener("click", function () {
          if (state.sortBy === key) state.sortDir = (state.sortDir === "asc" ? "desc" : "asc");
          else { state.sortBy = key; state.sortDir = "asc"; }
          state.page = 0;
          load();
        });
      })(ths[i]);
    }

    load();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", wireUp);
  else wireUp();
})();
